{"file_path":"src/parser.js","content":"import { InputError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/**
 * Parses election input text into `{ candidates, ballots }`, where
 * `candidates` is the array of declared names in declaration order and
 * `ballots` is an array of `{ count, candidates }`. Throws `InputError` on
 * any malformed input.
 */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  let candidatesDeclared = false
  const candidateOrder = []
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidatesDeclared) {
        throw new InputError('candidates must be declared once, before any ballot', lineNo)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new InputError('expected candidates <name>...', lineNo)
      }
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new InputError(`invalid candidate name ${name}`, lineNo)
        }
        if (candidateSet.has(name)) {
          throw new InputError(`candidate ${name} is declared twice`, lineNo)
        }
        candidateSet.add(name)
        candidateOrder.push(name)
      }
      candidatesDeclared = true
    } else if (directive === 'ballot') {
      if (!candidatesDeclared) {
        throw new InputError('candidates must be declared once, before any ballot', lineNo)
      }
      const rest = tokens.slice(1)
      if (rest.length < 2) {
        throw new InputError('expected ballot <count> <candidate>...', lineNo)
      }
      const countStr = rest[0]
      if (!COUNT_RE.test(countStr)) {
        throw new InputError('count must be a positive integer', lineNo)
      }
      const count = Number.parseInt(countStr, 10)
      const names = rest.slice(1)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new InputError(`unknown candidate ${name}`, lineNo)
        }
        if (seen.has(name)) {
          throw new InputError(`candidate ${name} is repeated`, lineNo)
        }
        seen.add(name)
      }
      ballots.push({ count, candidates: names })
    } else {
      throw new InputError(`unknown directive ${directive}`, lineNo)
    }
  }

  if (!candidatesDeclared) {
    throw new InputError('no candidates')
  }

  return { candidates: candidateOrder, ballots }
}
"}

