{"file_path":"src/election.js","content":"/**
 * Runs the instant-runoff count for an election parsed by `parseElection`.
 * Returns `{ rounds, winner }`, where `rounds` is an array of
 * `{ counts, exhausted, eliminated }` (one per round counted, in order;
 * `counts` maps candidate name to votes for every candidate continuing that
 * round, `eliminated` is the name eliminated after the round or `null` when
 * the round ended the election) and `winner` is the winning candidate's
 * name or `null` when nobody won.
 */
export function runElection(election) {
  const { candidates, ballots } = election

  let continuing = new Set(candidates)
  const roundHistory = [] // array of Map(name -> votes), one per round counted
  const rounds = []
  let winner = null

  for (;;) {
    const tally = new Map()
    for (const name of continuing) tally.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.candidates.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        tally.set(choice, tally.get(choice) + ballot.count)
      }
    }

    roundHistory.push(tally)

    const activeTotal = [...tally.values()].reduce((a, b) => a + b, 0)

    const counts = {}
    for (const [name, votes] of tally) counts[name] = votes

    if (activeTotal === 0) {
      rounds.push({ counts, exhausted, eliminated: null })
      winner = null
      break
    }

    let majorityWinner = null
    for (const [name, votes] of tally) {
      if (votes * 2 > activeTotal) {
        majorityWinner = name
        break
      }
    }

    if (majorityWinner !== null) {
      rounds.push({ counts, exhausted, eliminated: null })
      winner = majorityWinner
      break
    }

    const eliminated = pickElimination(tally, roundHistory)
    rounds.push({ counts, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

function pickElimination(tally, roundHistory) {
  let fewest = Infinity
  for (const votes of tally.values()) fewest = Math.min(fewest, votes)
  let tied = [...tally.keys()].filter((name) => tally.get(name) === fewest)

  for (;;) {
    let narrowed = false
    for (const round of roundHistory) {
      const votes = tied.map((name) => round.get(name))
      const min = Math.min(...votes)
      const allEqual = votes.every((v) => v === votes[0])
      if (!allEqual) {
        tied = tied.filter((name) => round.get(name) === min)
        narrowed = true
        break
      }
    }
    if (!narrowed) break
    if (tied.length === 1) break
  }

  if (tied.length === 1) return tied[0]

  return tied.reduce((last, name) => (name > last ? name : last))
}
"}

